    }
    pub fn next(self: *BTreeMap) ?MessageEntry {
        if (self.entries.items.len == 0) return null;
        return self.entries.orderedRemove(0);
    }
};

const BTreeSet = struct {
    map: *BTreeMap,

    pub fn _create(allocator: std.mem.Allocator) !*BTreeSet {
        const self = try allocator.create(BTreeSet);
        self.map = try BTreeMap._create(allocator);
        return self;
    }
    pub fn init(self: *BTreeSet) void { _ = self; }
    pub fn release(self: *BTreeSet) void {
        const alloc = self.map.allocator;
        self.map.release();
        alloc.destroy(self);
    }
    pub fn add(self: *BTreeSet, val: anytype) bool {
        return self.map.insert(val, true) == null;
    }
    pub fn has(self: *BTreeSet, val: anytype) bool {
        return self.map.has(val);
    }
    pub fn remove(self: *BTreeSet, val: anytype) ?Message {
        if (self.map.remove(val) != null) return cp_message_from(true);
        return null;
    }
    pub fn delete(self: *BTreeSet, val: anytype) bool { return self.map.delete(val); }
    pub fn min(self: *BTreeSet) ?Message { return self.map.min_key(); }
    pub fn max(self: *BTreeSet) ?Message { return self.map.max_key(); }
    pub fn len(self: *BTreeSet) usize { return self.map.len(); }
    pub fn size(self: *BTreeSet) i32 { return self.map.size(); }
    pub fn is_empty(self: *BTreeSet) bool { return self.map.is_empty(); }
    pub fn clear(self: *BTreeSet) void { self.map.clear(); }
    pub fn values(self: *BTreeSet) []Message { return self.map.keys(); }
    pub fn next(self: *BTreeSet) ?Message {
        if (self.map.next()) |entry| { return entry.key; }
        return null;
    }
