pub const BaseContext = struct { pc: u32 = 0, _self: PID = undefined, _parent: ?*anyopaque = null, _parent_fn: ?*const fn(*anyopaque) anyerror!void = null, arena: ?*std.heap.ArenaAllocator = null, received_msg: ?Message = null, received_sender: ?PID = null, await_result: ?Message = null, };

pub const ZigSharedTensor = struct {
    ref_count: std.atomic.Value(u32),
    data: []u8,
    allocator: std.mem.Allocator,
    pub fn create(allocator: std.mem.Allocator, size: usize) !*ZigSharedTensor {
        const ptr = try allocator.create(ZigSharedTensor);
        ptr.data = try allocator.alloc(u8, size);
        ptr.ref_count = std.atomic.Value(u32).init(1);
        ptr.allocator = allocator;
        return ptr;
    }
    pub fn retain(self: *ZigSharedTensor) void {
