    }
    pub fn release(self: *ZigSharedTensor) void {
        if (self.ref_count.fetchSub(1, .release) == 1) {
            _ = self.ref_count.load(.acquire);
            self.allocator.free(self.data);
            self.allocator.destroy(self);
        }
    }
};

// --- Native Reactor Registry ---
threadlocal var poll_fds: [1024]std.posix.pollfd = undefined;
threadlocal var fd_to_ctx: [1024]*anyopaque = undefined;
threadlocal var fd_to_run: [1024]*const fn(*anyopaque) anyerror!void = undefined;
threadlocal var active_fds: usize = 0;
fn register_fd(fd: i32, run: *const fn(*anyopaque) anyerror!void, ctx: *anyopaque, events: i16) void {
    if (active_fds < 1024) {
        poll_fds[active_fds] = .{ .fd = fd, .events = events, .revents = 0 };
        fd_to_ctx[active_fds] = ctx;
        fd_to_run[active_fds] = run;
        active_fds += 1;
    }
}

// --- Scheduler ---
